<?php
declare(strict_types=1);
function envv(string $k,string $d=''):string { $v=getenv($k); return $v===false?$d:$v; }
function db():PDO { static $p=null; if($p)return $p; $host=envv('DB_HOST','127.0.0.1');$port=envv('DB_PORT','5432');$name=envv('DB_DATABASE','school_id_platform');$user=envv('DB_USERNAME','postgres');$pass=envv('DB_PASSWORD');$ssl=envv('DB_SSLMODE','prefer');$p=new PDO("pgsql:host=$host;port=$port;dbname=$name;sslmode=$ssl",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); return $p; }
function boot():void { static $done=false;if($done)return;$sql=file_get_contents(__DIR__.'/database/schema.postgresql.sql');foreach(explode(';',$sql) as $statement){$statement=trim($statement);if($statement!=='')db()->exec($statement);}$email=trim(envv('OWNER_EMAIL'));$pw=envv('OWNER_PASSWORD');if($email!==''&&$pw!==''){$q=db()->prepare('INSERT INTO users(full_name,email,password_hash,is_platform_owner) VALUES(?,?,?,TRUE) ON CONFLICT(email) DO NOTHING');$q->execute([envv('OWNER_NAME','Platform Owner'),$email,password_hash($pw,PASSWORD_DEFAULT)]);}$done=true; }
boot();
if(session_status()!==PHP_SESSION_ACTIVE){session_name('msid_session');session_set_cookie_params(['httponly'=>true,'secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'samesite'=>'Lax']);session_start();}
function h($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function u():?array{return $_SESSION['user']??null;}
function go(string $p):never{header('Location: '.$p);exit;}
function need_login():void{if(!u())go('login.php');}
function owner():bool{return !empty(u()['is_platform_owner']);}
function school_id():int{return (int)(u()['school_id']??0);}
function role():string{return (string)(u()['role_key']??'');}
function need_owner():void{need_login();if(!owner()){http_response_code(403);exit('Platform Owner access required.');}}
function need_school(array $roles=[]):void{need_login();if(owner()||school_id()<1||($roles&&!in_array(role(),$roles,true))){http_response_code(403);exit('You do not have permission to access this page.');} $s=db()->prepare("SELECT status FROM schools WHERE id=?");$s->execute([school_id()]);if($s->fetchColumn()!=='active'){http_response_code(403);exit('This school account is not active.');}}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function check_csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['_csrf']??'')){http_response_code(419);exit('Invalid form token.');}}
function audit_log(string $action,array $data=[]):void{$q=db()->prepare('INSERT INTO audit_logs(school_id,user_id,action,details_json) VALUES(?,?,?,?::jsonb)');$q->execute([school_id()?:null,u()['id']??null,$action,json_encode($data)]);}
function assigned_class_ids():array{$q=db()->prepare('SELECT class_id FROM class_assignments WHERE school_id=? AND user_id=?');$q->execute([school_id(),u()['id']]);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}
function can_manage_students():bool{return in_array(role(),['director','dos'],true);}
function page(string $title,string $body):void{$me=u();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?></title><link rel="stylesheet" href="assets/style.css"><style>body{background:#f4f7fb}.wrap{max-width:1180px;margin:30px auto;padding:0 18px}.top{background:#123f72;color:#fff;padding:17px 24px;display:flex;justify-content:space-between;align-items:center}.top a{color:#fff;margin-left:16px}.panel{background:#fff;padding:22px;border-radius:12px;box-shadow:0 4px 18px #16395b12;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px}.stat{font-size:28px;font-weight:700;color:#123f72}input,select{padding:10px;border:1px solid #ccd5e0;border-radius:7px;width:100%;box-sizing:border-box;margin:5px 0 12px}button,.btn{background:#123f72;color:#fff;border:0;padding:10px 16px;border-radius:7px;cursor:pointer;text-decoration:none;display:inline-block}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #e6ebf1}.muted{color:#68778a}.danger{color:#a22}.nav a{margin-right:12px}</style></head><body><header class="top"><strong>Multi-School ID Platform</strong><div><?php if($me):?><?=h($me['full_name'])?> · <?=h(owner()?'Platform Owner':ucfirst(role()))?> <a href="index.php">Dashboard</a><a href="logout.php">Logout</a><?php endif;?></div></header><main class="wrap"><h1><?=h($title)?></h1><?php if($me&&!owner()):?><div class="panel nav"><a href="students.php">Students</a><a href="classes.php">Classes</a><?php if(in_array(role(),['director','dos'])):?><a href="student_add.php">Register student</a><?php endif;?><?php if(role()==='director'):?><a href="staff.php">Staff</a><a href="settings.php">School settings</a><?php endif;?><a href="bulk_cards.php">Print cards</a></div><?php endif;?><?=$body?></main></body></html><?php }
function cloud_upload(string $field):?string{if(empty($_FILES[$field]['tmp_name']))return null;$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024)throw new RuntimeException('Image must be smaller than 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))throw new RuntimeException('Use JPG, PNG or WEBP images.');$cloud=envv('CLOUDINARY_CLOUD_NAME');$key=envv('CLOUDINARY_API_KEY');$secret=envv('CLOUDINARY_API_SECRET');if(!$cloud||!$key||!$secret)throw new RuntimeException('Configure Cloudinary credentials first.');$ts=time();$folder=envv('CLOUDINARY_FOLDER','school-id-platform');$params=['folder'=>$folder,'timestamp'=>$ts];ksort($params);$parts=[];foreach($params as $k=>$v)$parts[]="$k=$v";$sig=sha1(implode('&',$parts).$secret);$ch=curl_init("https://api.cloudinary.com/v1_1/".rawurlencode($cloud)."/image/upload");curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_POSTFIELDS=>$params+['api_key'=>$key,'signature'=>$sig,'file'=>new CURLFile($f['tmp_name'])],CURLOPT_TIMEOUT=>45]);$r=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$j=json_decode((string)$r,true);if($code<200||$code>=300||empty($j['secure_url']))throw new RuntimeException('Image upload failed.');return $j['secure_url'];}
